// Velure - review request. Runs daily; the Notion query limits to Completed + not yet asked.
// Shared Velure email shell (inline styles only — email clients ignore <style> blocks)
const shell = (title, bodyHtml) => `<!doctype html><html><body style="margin:0;padding:0;background:#FAF6F1;">
<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="background:#FAF6F1;padding:40px 16px;">
<tr><td align="center">
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;background:#FFFFFF;border:1px solid #EFE6DA;border-radius:14px;">
<tr><td style="padding:40px 40px 8px 40px;font-family:Georgia,'Times New Roman',serif;font-size:26px;letter-spacing:-0.5px;color:#2B2420;">Velure</td></tr>
<tr><td style="padding:0 40px;font-family:Helvetica,Arial,sans-serif;font-size:10px;letter-spacing:3px;text-transform:uppercase;color:#B08968;">Med Spa &middot; Scottsdale</td></tr>
<tr><td style="padding:28px 40px 0 40px;"><div style="height:1px;background:#EFE6DA;line-height:1px;">&nbsp;</div></td></tr>
<tr><td style="padding:28px 40px 0 40px;font-family:Georgia,'Times New Roman',serif;font-size:24px;line-height:1.25;color:#2B2420;">${title}</td></tr>
<tr><td style="padding:16px 40px 36px 40px;font-family:Helvetica,Arial,sans-serif;font-size:15px;line-height:1.65;color:#4A3F39;">${bodyHtml}</td></tr>
</table>
<table role="presentation" width="560" cellpadding="0" cellspacing="0" style="max-width:560px;width:100%;">
<tr><td style="padding:20px 8px;font-family:Helvetica,Arial,sans-serif;font-size:11px;line-height:1.6;color:#8A7D74;text-align:center;">
Velure Med Spa &middot; 1200 Desert Bloom Ave, Scottsdale, AZ &middot; (480) 555-0142<br>
Velure is a fictional brand created as a demonstration project by <a href="https://thaus.co" style="color:#8A7D74;">Thaus</a>.
</td></tr></table>
</td></tr></table></body></html>`;
const esc = (v) => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const row = (k, v) => `<tr><td style="padding:6px 0;color:#8A7D74;width:120px;vertical-align:top;">${k}</td><td style="padding:6px 0;color:#2B2420;">${v}</td></tr>`;

// ---- read a Notion page whether "Simplify" is on (property_*) or off (properties.*) ----
const snake = (n) => 'property_' + n.toLowerCase().replace(/[^a-z0-9]+/g, '_');
const raw = (j, name) => (j.properties || {})[name];
const text = (v) => (Array.isArray(v) ? v.map((x) => x.plain_text || '').join('') : (v ?? ''));
const prop = (j, name) => (j[snake(name)] !== undefined ? j[snake(name)] : raw(j, name));
const str = (j, name) => {
  const v = prop(j, name);
  if (v == null) return '';
  if (typeof v === 'string') return v;
  if (v.email !== undefined) return v.email || '';
  if (v.select !== undefined) return (v.select && v.select.name) || '';
  if (v.rich_text !== undefined) return text(v.rich_text);
  if (v.title !== undefined) return text(v.title);
  if (v.phone_number !== undefined) return v.phone_number || '';
  return '';
};
const dateStart = (j, name) => {
  const v = prop(j, name);
  if (!v) return '';
  if (typeof v === 'string') return v;
  if (v.start) return v.start;
  if (v.date && v.date.start) return v.date.start;
  if (v.created_time) return v.created_time;
  return '';
};
const flag = (j, name) => {
  const v = prop(j, name);
  return typeof v === 'object' && v !== null ? !!v.checkbox : !!v;
};
const title = (j) => j.name || str(j, 'Client');
// Appointments are stored in Phoenix time (UTC-7, no DST). Strings without an offset are Phoenix local.
const PHX = 7 * 3600 * 1000;
const toMs = (s) => (/[zZ]$|[+-]\d\d:\d\d$/.test(s) ? Date.parse(s) : Date.parse(s + '-07:00'));
const DAYS = ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'];
const MONTHS = ['January','February','March','April','May','June','July','August','September','October','November','December'];
const labels = (ms) => {
  const d = new Date(ms - PHX); // read the UTC fields as Phoenix wall time
  const h = d.getUTCHours(), m = d.getUTCMinutes();
  return {
    dateLabel: `${DAYS[d.getUTCDay()]}, ${MONTHS[d.getUTCMonth()]} ${d.getUTCDate()}`,
    timeLabel: `${((h + 11) % 12) + 1}:${String(m).padStart(2, '0')} ${h < 12 ? 'AM' : 'PM'}`,
  };
};

// Replace with your real review page (for example a Google review link) when the business has one.
const REVIEW_URL = 'https://velure-medspa.vercel.app/#contact';
// Ignore visits older than this (e.g. a booking marked Completed weeks late).
const MAX_AGE_DAYS = 14;
const now = Date.now();
const out = [];

for (const item of $input.all()) {
  const j = item.json;
  const email = str(j, 'Email').trim();
  const startStr = dateStart(j, 'Appointment');
  if (!email) continue;

  if (startStr) {
    const when = toMs(startStr);
    if (!Number.isNaN(when)) {
      const daysAgo = (now - when) / 86400000;
      if (daysAgo < 0 || daysAgo > MAX_AGE_DAYS) continue;
    }
  }

  const fullName = title(j) || 'there';
  const firstName = fullName.split(' ')[0] || 'there';
  const treatment = str(j, 'Treatment');

  const html = shell(
    `How was your visit, ${esc(firstName)}?`,
    `<p style="margin:0 0 14px 0;">Thank you for spending time with us${treatment ? ` for your ${esc(treatment)}` : ''}. We hope you left feeling looked after.</p>
     <p style="margin:0 0 22px 0;">If you have a minute, a few honest words about your experience would mean a great deal to us, and help others choose with confidence.</p>
     <p style="margin:0 0 26px 0;"><a href="${REVIEW_URL}" style="display:inline-block;padding:14px 28px;background:#2B2420;color:#FAF6F1;border-radius:999px;text-decoration:none;font-family:Helvetica,Arial,sans-serif;font-size:14px;">Share your feedback</a></p>
     <p style="margin:0;">Something we should put right? Simply reply to this email and a member of our team will respond personally.</p>
     <p style="margin:22px 0 0 0;color:#2B2420;">With care,<br>The Velure team</p>`
  );

  out.push({ json: {
    pageId: j.id, email, html,
    subject: `How was your visit, ${firstName}?`,
  } });
}

return out;
